package oop.exercises.domain;public class Pessoa {    private String name;    private int age;    private String profission;    public Pessoa(String name, int age){        this();        this.name = name;        this.age = age;    }    public Pessoa(String name, int age, String profission){        this(name, age);        this.profission = profission;    }    public Pessoa(){        System.out.println("Construtor pessoa not arguments");    }    public void setName(String name) {        this.name = name;    }    public void setAge(int age) {        this.age = age;    }    public void setProfission(String profission) {        this.profission = profission;    }    public void imprimir(){        System.out.println(this.name);        System.out.println(this.age);        System.out.println(this.profission);    }    public String getName() {        return name;    }    public int getAge() {        return age;    }    public String getProfission() {        return profission;    }}